using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
internal static class Revision127Specs
{
 static Dictionary<string,string> R(params string[] fields)=>fields.ToDictionary(s=>s[..s.IndexOf('=')],s=>s[(s.IndexOf('=')+1)..]);
 static RouterAuditConfig Fixture(){var c=new RouterAuditConfig();foreach(var key in RouterAuditReader.Commands.Keys)c.Tables[key]=[];c.Tables["interfaces"]=[R("name=uplink"),R("name=inside")];c.Tables["lists"]=[R("name=WAN")];c.Tables["members"]=[R("list=WAN","interface=uplink")];c.Tables["addresses4"]=[R("address=198.51.100.2/24","interface=uplink"),R("address=10.23.0.1/24","interface=inside"),R("address=10.23.0.1/24","interface=inside")];c.Tables["dns"]=[R("allow-remote-requests=yes")];c.Tables["ipv6-settings"]=[R("disable-ipv6=yes")];c.Tables["mac"]=[R("allowed-interface-list=none")];c.Tables["mac-winbox"]=[R("allowed-interface-list=none")];c.Tables["neighbors"]=[R("discover-interface-list=none")];c.Tables["filter4"]=[R(".id=*F","chain=input","action=drop"),R(".id=*G","chain=forward","action=accept","connection-nat-state=dstnat")];c.Tables["nat4"]=[R(".id=*A","chain=dstnat","action=dst-nat","protocol=tcp","dst-port=34634","to-addresses=10.23.0.8","to-ports=3389")];return c;}
 public static void Run(Action<string,bool> check){
  var c=Fixture();var result=RouterAudit.Analyze(c);var publication=result.Findings.Single(f=>f.Key.StartsWith("nat:tcp:")&&f.Key.EndsWith(":3389"));
  check("NAT report evaluates WAN destinations without internal address duplicates",publication.Evidence.Split("Путь в конфигурации:").Length==2&&!publication.Evidence.Contains("вход uplink · 10.23.0.1:"));
  check("NAT report does not claim external provider reachability",publication.Recommendation.Contains("не проверялись"));
  var dns=result.Findings.Where(f=>f.Key.StartsWith("dns:")).ToArray();check("DNS transports share one problem card with both paths",dns.Length==1&&dns[0].Evidence.Contains("tcp/53")&&dns[0].Evidence.Contains("udp/53"));
  var fingerprint=dns[0].Fingerprint;c.Tables["addresses4"].Reverse();var reordered=RouterAudit.Analyze(c);check("Evidence order and repeated addresses preserve finding fingerprint",reordered.Findings.Single(f=>f.Key==dns[0].Key).Fingerprint==fingerprint);
  c.Tables["filter4"].Insert(0,R(".id=*U","chain=input","action=accept","protocol=udp","dst-port=53"));var mixed=RouterAudit.Analyze(c).Findings.Single(f=>f.Key.StartsWith("dns:"));check("Mixed DNS paths retain highest risk and individual closed result",mixed.Status=="Разрешено firewall: любые источники"&&mixed.Evidence.Contains("Результат пути: Закрыто")&&mixed.Commands.Contains("protocol=tcp")&&mixed.Commands.Contains("protocol=udp"));
  c=Fixture();c.Tables["nat4"][0]["dst-address"]="198.51.100.9";check("Explicit NAT destination remains evaluated outside assigned WAN addresses",RouterAudit.Analyze(c).Findings.Single(f=>f.Key.StartsWith("nat:")).Evidence.Contains("198.51.100.9:34634"));
  c=Fixture();c.Tables["raw4"]=[R(".id=*R","chain=prerouting","action=drop")];check("Early RAW block still closes all NAT paths after deduplication",RouterAudit.Analyze(c).Findings.Where(f=>f.Key.StartsWith("nat:")).All(f=>f.Status=="Закрыто"));
  c=Fixture();foreach(var name in new[]{"second","third"}){c.Tables["interfaces"].Add(R("name="+name));c.Tables["members"].Add(R("list=WAN","interface="+name));}check("Three WAN DNS checks produce three cards rather than six",RouterAudit.Analyze(c).Findings.Count(f=>f.Key.StartsWith("dns:"))==3);
  RouterAuditResult Finding(string fingerprint,Severity severity=Severity.Warning)=>new(){Findings=[new(){Key="fixture",Fingerprint=fingerprint,Title="Fixture",Status="Нужна проверка",Severity=severity}]};
  var state=new NetworkState();var history=new NetworkHistory{DeviceId=1};RouterAuditStore.Apply(state,history,Finding("a"),"fixture");RouterAuditStore.Apply(state,history,Finding("b"),"fixture");
  check("Changed evidence carries one pending notification forward",state.Notifications.Count==1&&state.Notifications[0].EntityKey.Contains(":summary:")&&state.Notifications[0].HandledAt==null);
  state.Notifications[0].HandledAt=DateTime.UtcNow;state.Notifications[0].Result="Отправлено";RouterAuditStore.Apply(state,history,Finding("c"),"fixture");check("Changed evidence does not resend already delivered unresolved problem",state.Notifications.Count==1);
  RouterAuditStore.Apply(state,history,Finding("c2"),"fixture");check("Repeated evidence changes preserve same notification episode",state.Notifications.Count==1);
  RouterAuditStore.Apply(state,history,Finding("d",Severity.Critical),"fixture");check("Severity escalation still queues a new notification",state.Notifications.Count==2&&state.Notifications.Last().Severity==Severity.Critical);
  var legacy=new NetworkState();var legacyHistory=new NetworkHistory{DeviceId=2};var legacyResult=new RouterAuditResult{Findings=[new(){Key="dns:32:uplink:tcp",Fingerprint="tcp",Severity=Severity.Warning},new(){Key="dns:32:uplink:udp",Fingerprint="udp",Severity=Severity.Warning}]};RouterAuditStore.Apply(legacy,legacyHistory,legacyResult,"legacy");RouterAuditStore.Apply(legacy,legacyHistory,new(){Findings=[new(){Key="dns:32:uplink",Fingerprint="both",Severity=Severity.Warning}]},"legacy");check("Legacy TCP UDP pending alerts collapse to one DNS notification",legacy.Notifications.Count(n=>n.HandledAt==null)==1);
  RouterAuditStore.Apply(state,history,new(),"fixture");RouterAuditStore.Apply(state,history,Finding("e"),"fixture");check("Resolved problem can notify on a new episode",state.Notifications.Any(n=>n.EntityKey.Contains(":summary:")&&n.HandledAt==null));
 }
}
